def adjudicate_chain_fork_aggregate_proofs(items, prune_policy, site_policy,
                                           authorization_policy, keyring,
                                           moment, issuer, version):
    """Adjudicate multi-site chain fork aggregate proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_chain_fork_aggregate_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against and ``site_policy`` the
    fork-proof site policy their payloads digest; ``authorization_policy``
    additionally carries exactly ``sites`` (a non-empty map of each
    authorized non-empty signing site to its non-empty set of allowed
    positive key versions) and ``threshold`` (a positive integer no
    greater than the site count).  ``keyring`` follows the existing
    rules, ``moment`` is the non-negative adjudication moment and
    ``issuer``/``version`` name the adjudicator credentials.  No file is
    read or written and no input is modified.

    Every proof is first independently re-verified through the chain
    fork aggregate proof rules (a structurally illegal, foreign-policy
    or future-dated proof is ``invalid-proof`` carrying no identity),
    then authorized precisely by the exact payload identity and key
    version against the authorization policy with no fallback
    (``unauthorized-site``, ``unauthorized-version``), then
    authenticated against the current keyring
    (``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired``, ``bad-signature``); one item's rejection never blocks a
    later item.  For one site, proofs whose complete fork edge set --
    every edge of root digest, forking predecessor digest and the
    ascending set of legal successor digests -- is identical count once
    and every extra proof is ``duplicate``, while two distinct complete
    edge sets from one site are a ``contradiction``.  Distinct sites
    must agree exactly on the complete edge set; any same-site
    contradiction or cross-site difference is ``conflicted`` with a null
    common set and can never be outvoted by a majority.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold is
    ``insufficient`` yet still binds that common set; with no valid vote
    at all the common set is null.

    The packet is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``; the payload binds
    exactly the two policy digests -- ``prunePolicyDigest`` and
    ``authorizationPolicyDigest`` (the SHA-256 of the canonical site
    authorization policy) -- together with ``common`` (the
    stable-sorted common fork edge set, or null), ``issuer``, ``items``
    (the rows stably sorted by site then id, each carrying
    ``conclusion``, the authenticated ``edges`` or null, ``id``,
    ``issuer``, ``keyVersion``, the proof ``digest`` and ``reason``),
    ``keyVersion``, ``proofs`` (each input proof's SHA-256 in the
    original input order), ``status`` and ``version`` (the integer 1).
    The fork-proof site policy is already digested inside every signed
    proof and so is not repeated in the decision.  The signature is the
    lowercase hex HMAC-SHA256 of the canonical payload bytes under the
    exact adjudicator issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal policy, threshold,
    moment, issuer or version raises :class:`ValueError`; unknown,
    revoked, not-yet-valid or expired adjudicator credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()

    # The proof summaries keep the original input order, independent of
    # the stably sorted conclusion rows.
    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_cfa_one(
            item, prune_policy_digest, site_policy_digest,
            validated_authorization_policy, validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _CF_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_authorization_policy[ADJ_THRESHOLD]:
            status = _CF_STATUS_ACCEPTED
        else:
            status = _CF_STATUS_INSUFFICIENT
    else:
        status = _CF_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        _CF_DECISION_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        _CF_DECISION_PROOFS: proof_digests,
        _CFA_AUTHZ_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_authorization_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: CHAIN_FORK_AGGREGATE_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_cfa_decision(raw: object) -> tuple[dict, str]:
    """Validate chain fork aggregate decision bytes structurally.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidChainDecisionError`.  The policy, tally and
    credential bindings are checked by the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_decision_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_decision_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=lambda pairs: _reject_duplicate_pafd_keys(
                pairs, _cfa_decision_invalid
            ),
        )
    except json.JSONDecodeError as exc:
        raise _cfa_decision_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _cfa_decision_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_decision_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _CFA_DECISION_PAYLOAD_KEYS:
        raise _cfa_decision_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'authorizationPolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_decision_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cfa_decision_invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise _cfa_decision_invalid("payload status is not a known status")
    for field in (PAFD_PRUNE_POLICY_DIGEST, _CFA_AUTHZ_POLICY_DIGEST):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise _cfa_decision_invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise _cfa_decision_invalid("payload items must be non-empty")
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise _cfa_decision_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'digest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _cfa_decision_invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise _cfa_decision_invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[_CF_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_decision_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise _cfa_decision_invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _cfa_decision_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _cfa_decision_invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise _cfa_decision_invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise _cfa_decision_invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise _cfa_decision_invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise _cfa_decision_invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise _cfa_decision_invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            if not raw_edges:
                raise _cfa_decision_invalid(
                    f"{where} edges must be non-empty for an authenticated "
                    "proof"
                )
            row_edges = [
                _validated_pafd_edge(value, where, _cfa_decision_invalid)
                for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise _cfa_decision_invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise _cfa_decision_invalid(
                    f"{where} edges must be sorted ascending"
                )
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise _cfa_decision_invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise _cfa_decision_invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        if not common:
            raise _cfa_decision_invalid(
                "a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(value, "payload common",
                                 _cfa_decision_invalid)
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _cfa_decision_invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != CHAIN_FORK_AGGREGATE_DECISION_VERSION:
        raise _cfa_decision_invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise _cfa_decision_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def verify_chain_fork_aggregate_decision(decision, prune_policy,
                                         authorization_policy, keyring,
                                         moment):
    """Re-verify a signed chain fork aggregate decision entirely offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    expected site ``authorization_policy``, the current ``keyring`` and
    the verification ``moment`` are consulted -- no file is read or
    written and no argument is modified.  The decision binds the two
    policy digests (the prune policy and the site authorization
    policy); the fork-proof site policy is already digested inside
    every signed proof the decision rows name.  Verification validates
    the canonical encoding and every key set, recomputes both policy
    digests, re-tallies the bound per-proof rows purely from the signed
    payload (the stable site/id row ordering, the original-order proof
    digest vector as a multiset independent of the row order, the
    same-site duplicate/contradiction markings, the cross-site complete
    edge-set agreement, the authorization threshold outcome and the
    claimed common set), and checks the HMAC-SHA256 against the key the
    current keyring binds to the payload's exact issuer and version,
    usable at the verification moment, so a later revocation or expiry
    rejects the decision with no fallback.

    On success a fresh depth-independent mapping is returned with the
    fixed keys ``common``, ``proofDigest`` (the SHA-256 of the decision
    bytes), ``issuer``, ``items``, ``keyVersion``,
    ``prunePolicyDigest``, ``proofs``, ``authorizationPolicyDigest``,
    ``status`` and ``version`` (the integer 1); repeated calls return
    equal but mutually independent objects.  A non-bytes decision or a
    wrong public field type raises :class:`TypeError` (a :class:`bool`
    never poses as an int); an empty value, a duplicate id, a wrong key
    set or an illegal policy, threshold, moment, site or version raises
    :class:`ValueError`; an illegal decision structure, ordering, tally
    or binding raises :class:`InvalidChainDecisionError` (a
    :class:`ValueError` subclass, distinct from
    :class:`InvalidChainProofError`); unknown, revoked, not-yet-valid or
    expired credentials or a wrong signature raise
    :class:`AuthenticationError`.
    """
    if not isinstance(decision, bytes):
        raise TypeError("decision must be bytes")
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_authorization_policy = _validated_prune_batch_site_policy(
        authorization_policy
    )
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    payload, signature = _parse_cfa_decision(decision)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PAFD_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _cfa_decision_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_authorization_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_authorization_policy)
    ).hexdigest()
    if payload[_CFA_AUTHZ_POLICY_DIGEST] != expected_authorization_digest:
        raise _cfa_decision_invalid(
            "authorization policy digest does not match the authorization "
            "policy"
        )

    # The proof digest vector stays in the original input order, so only
    # its multiset must agree with the stably sorted rows.
    status = _reconcile_pafd(
        payload, validated_authorization_policy[ADJ_THRESHOLD],
        invalid=_cfa_decision_invalid, positional_proofs=False,
    )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "chain fork aggregate decision signature does not match"
        )

    return {
        key: copy.deepcopy(value)
        for key, value in (
            (PAFD_COMMON, payload[PAFD_COMMON]),
            (FORK_PROOF_DIGEST, hashlib.sha256(decision).hexdigest()),
            (VD_ISSUER, payload[VD_ISSUER]),
            (ITEMS, payload[ITEMS]),
            (KEY_VERSION, payload[KEY_VERSION]),
            (PAFD_PRUNE_POLICY_DIGEST, expected_prune_digest),
            (PAFD_PROOFS, payload[PAFD_PROOFS]),
            (_CFA_AUTHZ_POLICY_DIGEST, expected_authorization_digest),
            (STATUS, status),
            (VERSION, CHAIN_FORK_AGGREGATE_DECISION_VERSION),
        )
    }

_PAFD_STATUS_ACCEPTED = PA_STATUS_ACCEPTED
_PAFD_STATUS_CONFLICTED = PA_STATUS_CONFLICTED
_PAFD_STATUS_INSUFFICIENT = PA_STATUS_INSUFFICIENT
_PAFD_STATUSES = frozenset((
    _PAFD_STATUS_ACCEPTED,
    _PAFD_STATUS_CONFLICTED,
    _PAFD_STATUS_INSUFFICIENT,
))

_PAFD_CONCLUSION_VALID = ADJ_CONCLUSION_VALID
_PAFD_CONCLUSION_INVALID = ADJ_CONCLUSION_INVALID
_PAFD_CONCLUSION_DUPLICATE = ADJ_CONCLUSION_DUPLICATE
_PAFD_CONCLUSION_CONTRADICTION = ADJ_CONCLUSION_CONTRADICTION
_PAFD_CONCLUSIONS = frozenset((
    _PAFD_CONCLUSION_VALID,
    _PAFD_CONCLUSION_INVALID,
    _PAFD_CONCLUSION_DUPLICATE,
    _PAFD_CONCLUSION_CONTRADICTION,
))

_PAFD_REASON_INVALID_PROOF = PA_REASON_INVALID_PROOF
_PAFD_INVALID_REASONS = frozenset((
    _PAFD_REASON_INVALID_PROOF,
    REASON_UNAUTHORIZED_SITE,
    REASON_UNAUTHORIZED_VERSION,
    REASON_CREDENTIAL_UNAVAILABLE,
    REASON_REVOKED,
    REASON_NOT_YET_VALID,
    REASON_EXPIRED,
    REASON_BAD_SIGNATURE,
))
_PAFD_REASONS = _PAFD_INVALID_REASONS | frozenset((
    REASON_DUPLICATE,
    REASON_CONTRADICTION,
))

_PAFD_ITEM_KEYS = frozenset((ID, FORK_PROOF_ITEM_PROOF))
_PAFD_DECISION_TOP_KEYS = frozenset((TICKET_PAYLOAD, SIGNATURE))
_PAFD_PAYLOAD_KEYS = frozenset((
    PAFD_COMMON,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    PAFD_SITE_POLICY_DIGEST,
    STATUS,
    VERSION,
))
_PAFD_EDGE_KEYS = frozenset((
    PAC_ROOT_DIGEST,
    PAC_PREDECESSOR_DIGEST,
    PAC_BATCH_SUCCESSORS,
))
_PAFD_ROW_KEYS = frozenset((
    ADJ_CONCLUSION,
    PAFD_EDGES,
    ID,
    KEY_VERSION,
    PAFD_FORK_PROOF_DIGEST,
    ADJ_REASON,
    VD_ISSUER,
))
_PAFD_RESULT_KEYS = (
    PAFD_COMMON,
    FORK_PROOF_DIGEST,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    PAFD_SITE_POLICY_DIGEST,
    STATUS,
    VERSION,
)


class InvalidAggregateForkDecisionError(ValueError):
    """A signed prune aggregate fork decision breaks its binding contract."""


def _pafd_invalid(message: str) -> InvalidAggregateForkDecisionError:
    return InvalidAggregateForkDecisionError(
        f"invalid prune aggregate fork decision: {message}"
    )


def _reject_duplicate_pafd_keys(pairs: list[tuple], invalid=_pafd_invalid) -> dict:
    """``object_pairs_hook`` turning duplicate decision keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_fork_edge_object(entry: dict) -> dict:
    """One canonical ``{rootDigest, predecessorDigest, successors}`` edge."""
    return {
        PAC_ROOT_DIGEST: entry[PAC_ROOT_DIGEST],
        PAC_PREDECESSOR_DIGEST: entry[PAC_PREDECESSOR_DIGEST],
        PAC_BATCH_SUCCESSORS: list(entry[PAC_BATCH_SUCCESSORS]),
    }


def _pac_fork_proof_edges(payload: dict) -> list[dict]:
    """The complete fork edge set a verified fork proof binds.

    The proof parser already validated every fork entry, its ordering
    and its successor set, so the entries are copied verbatim in the
    report's own canonical (root, predecessor, successor) order.
    """
    return [
        _pac_fork_edge_object(fork)
        for fork in payload[FORK_PROOF_REPORT][CHAINS_FORKS]
    ]


def _pac_fork_edge_triples(
    edges: list[dict],
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    """Order-preserving edge objects to comparable triples."""
    return tuple(
        (
            edge[PAC_ROOT_DIGEST],
            edge[PAC_PREDECESSOR_DIGEST],
            tuple(edge[PAC_BATCH_SUCCESSORS]),
        )
        for edge in edges
    )


def _sorted_pac_fork_edge_objects(
    triples: set | frozenset,
) -> list[dict]:
    """Unique fork edges sorted by (rootDigest, predecessorDigest, ...)."""
    return [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: list(successors),
        }
        for root_digest, predecessor, successors in sorted(triples)
    ]


def _validated_pafd_edge(value: object, where: str, invalid=_pafd_invalid) -> dict:
    """Validate one bound fork edge object into a fresh ordered dict.

    Every non-type structural fault is raised through ``invalid`` (the
    prune aggregate fork decision error by default), so the same
    validation backs the chain fork decision packet.
    """
    if not isinstance(value, dict):
        raise TypeError(f"{where} edge must be an object")
    if set(value.keys()) != _PAFD_EDGE_KEYS:
        raise invalid(
            f"{where} edge must contain exactly the keys 'predecessorDigest', "
            "'rootDigest' and 'successors'"
        )
    root_digest = value[PAC_ROOT_DIGEST]
    predecessor = value[PAC_PREDECESSOR_DIGEST]
    successors = value[PAC_BATCH_SUCCESSORS]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} edge rootDigest must be a str")
    if not isinstance(predecessor, str):
        raise TypeError(f"{where} edge predecessorDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} edge rootDigest must be 64 lowercase hex characters"
        )
    if not _prune_is_digest(predecessor):
        raise invalid(
            f"{where} edge predecessorDigest must be 64 lowercase hex "
            "characters"
        )
    if not isinstance(successors, list):
        raise TypeError(f"{where} edge successors must be a list")
    if not successors:
        raise invalid(f"{where} edge successors must be non-empty")
    for position, successor in enumerate(successors):
        if not isinstance(successor, str):
            raise TypeError(
                f"{where} edge successor {position} must be a str"
            )
        if not _prune_is_digest(successor):
            raise invalid(
                f"{where} edge successor {position} must be 64 lowercase "
                "hex characters"
            )
    if successors != sorted(successors) or len(set(successors)) != len(
        successors
    ):
        raise invalid(
            f"{where} edge successors must be unique and sorted ascending"
        )
    return {
        PAC_ROOT_DIGEST: root_digest,
        PAC_PREDECESSOR_DIGEST: predecessor,
        PAC_BATCH_SUCCESSORS: list(successors),
    }


def _pafd_row(
    item_id: str,
    proof_digest: str,
    site: str | None,
    key_version: int | None,
    edges: list[dict] | None,
    conclusion: str,
    reason: str | None,
) -> dict:
    """One per-proof decision row with the fixed bound key set."""
    return {
        ADJ_CONCLUSION: conclusion,
        PAFD_EDGES: edges,
        ID: item_id,
        KEY_VERSION: key_version,
        PAFD_FORK_PROOF_DIGEST: proof_digest,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _adjudicate_pac_fork_one(
    item: dict,
    prune_policy_digest: str,
    site_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one fork proof in isolation.

    The proof is first checked through the exact
    :func:`verify_prune_aggregate_fork_proof` structural rules, then the
    signing site and key version are authorized exactly against the site
    policy with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _pafd_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_pac_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _pafd_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # The proof must be bound to the exact shared prune policy and must
    # not be dated after the adjudication moment; a mismatch makes the
    # claimed identity untrustworthy, so the row carries none.
    if payload[RECEIPT_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = site_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _pafd_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


_PAFD_EDGE_SET = frozenset[tuple[str, str, tuple[str, ...]]]


def _pafd_content(row: dict) -> _PAFD_EDGE_SET:
    """The complete fork edge set one authenticated row declares."""
    return frozenset(_pac_fork_edge_triples(row[PAFD_EDGES]))


def _tally_pac_fork_rows(
    rows: list[dict],
) -> tuple[bool, dict[str, _PAFD_EDGE_SET]]:
    """Group authenticated rows per site by their complete edge sets.

    Two rows from one site are the same declaration only when their
    complete fork edge set -- every ``(rootDigest, predecessorDigest,
    successors)`` triple -- agrees, regardless of the proof digest.
    The smallest-id row of one identical set is the vote and extras are
    ``duplicate``, while two distinct edge sets from one site are both a
    ``contradiction``.  Returns ``(contradicted, votes)`` where

CHAIN_FORK_AGGREGATE_DECISION_VERSION = 1

_CFA_PROOFS_VERSION = 1
_CFA_PROOFS_VERIFIED = _CF_PROOFS_VERIFIED
_CFA_PROOFS_INVALID = _CF_PROOFS_INVALID
_CFA_PROOFS_UNAUTHENTICATED = _CF_PROOFS_UNAUTHENTICATED

_CFA_AUTHZ_POLICY_DIGEST = "authorizationPolicyDigest"

_CFA_DECISION_PAYLOAD_KEYS = frozenset((
    PAFD_COMMON,
    VD_ISSUER,
    ITEMS,
    KEY_VERSION,
    PAFD_PRUNE_POLICY_DIGEST,
    PAFD_PROOFS,
    _CFA_AUTHZ_POLICY_DIGEST,
    STATUS,
    VERSION,
))


def _cfa_proof_invalid(message: str) -> InvalidChainProofError:
    return InvalidChainProofError(
        f"invalid chain fork aggregate proof: {message}"
    )


def _cfa_decision_invalid(message: str) -> InvalidChainDecisionError:
    return InvalidChainDecisionError(
        f"invalid chain fork aggregate decision: {message}"
    )


def _reject_duplicate_cfa_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _cfa_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _parse_cfa_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate chain fork aggregate proof bytes structurally.

    Returns ``(payload, signature, chains)``.  A non-bytes argument or a
    public field of the wrong type raises :class:`TypeError` (a
    :class:`bool` never poses as an int); every encoding, key-set,
    version, digest, count, ordering, reference or report-binding fault
    raises :class:`InvalidChainProofError`.  The two policy bindings, the
    moment and the signature are checked by the proof verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _cfa_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _cfa_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_cfa_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _cfa_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _CF_PROOF_TOP_KEYS:
        raise _cfa_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _cfa_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _CF_PROOF_PAYLOAD_KEYS:
        raise _cfa_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'prunePolicy', 'report', 'sitePolicy' "
            "and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _cfa_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _cfa_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _cfa_proof_invalid("payload moment must be non-negative")
    for field in (CF_PROOF_PRUNE_POLICY, CF_PROOF_SITE_POLICY):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _cfa_proof_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != CHAIN_FORK_AGGREGATE_PROOF_VERSION:

    try:
        payload, signature = _parse_pafd(raw)
    except (TypeError, ValueError):
        return invalid_row()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]

    if payload[PAFD_PRUNE_POLICY_DIGEST] != prune_policy_digest:
        return invalid_row()
    if payload[PAFD_SITE_POLICY_DIGEST] != site_policy_digest:
        return invalid_row()
    try:
        _reconcile_pafd(payload, fork_threshold)
    except InvalidAggregateForkDecisionError:
        return invalid_row()

    def unauthenticated_row() -> dict:
        return _pfda_aggregate_row(
            item_id, decision_digest, site, key_version, None,
            PA_CONCLUSION_INVALID, PA_REASON_UNAUTHENTICATED,
        )

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None or key_entry[REVOKED]:
        return unauthenticated_row()
    if moment < key_entry[NOT_BEFORE] or moment > key_entry[NOT_AFTER]:
        return unauthenticated_row()

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return unauthenticated_row()

    # The exact-issuer HMAC above established the site/version
    # identity, so an authorized-policy miss may carry that identity.
    allowed_versions = decision_site_policy[ADJ_SITES].get(site)
    if allowed_versions is None or key_version not in allowed_versions:
        return _pfda_aggregate_row(
            item_id, decision_digest, site, key_version, None,
            PA_CONCLUSION_INVALID, PA_REASON_UNAUTHORIZED,
        )

    return _pfda_aggregate_row(
        item_id, decision_digest, site, key_version,
        _pfda_declaration(payload), PA_CONCLUSION_VALID, None,
    )


def _tally_pfda_rows(
    rows: list[dict], threshold: int
) -> tuple[str, dict | None]:
    """Mark duplicate/contradiction rows and derive the overall status.

    Rows from one site are the same declaration only when their
    complete declarations agree field for field -- the common fork edge
    set, every sorted per-item conclusion entry, the original-order
    proof digest vector and the overall status.  The smallest-id row of
    one identical group is the vote and exact repeats are ``duplicate``,
    while distinct declarations from one site contradict each other.
    Distinct sites must agree on that same complete declaration -- any
    field-level disagreement conflicts and no majority can outvote it.

    A conflict of either kind binds no declaration.  Otherwise the one
    unique agreed declaration, when one exists, is always carried:
    backed by at least the threshold of distinct sites the tally is
    ``accepted``, and short of the threshold it stays ``insufficient``
    but keeps that unique declaration.  With no valid vote at all the
    tally is ``insufficient`` with the declaration null.
    """
    by_site: dict[str, dict[bytes, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] in (
            PA_CONCLUSION_VALID,
            PA_CONCLUSION_DUPLICATE,
            PA_CONCLUSION_CONTRADICTION,
        ):
            content = _prune_compact(row[PFDA_DECLARATION])
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                content, []
            ).append(row)

    contradicted = False
    votes: dict[str, bytes] = {}
    representatives: dict[str, dict] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda row: row[ID])
                members[0][ADJ_CONCLUSION] = PA_CONCLUSION_CONTRADICTION
                members[0][ADJ_REASON] = REASON_CONTRADICTION
                for extra in members[1:]:
                    extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members.sort(key=lambda row: row[ID])
            members[0][ADJ_CONCLUSION] = PA_CONCLUSION_VALID
            members[0][ADJ_REASON] = None
            for extra in members[1:]:
                extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
            representatives[site] = members[0]

    contents = set(votes.values())
    if contradicted or len(contents) > 1:
        return PA_STATUS_CONFLICTED, None
    if len(contents) == 1:
        first_site = min(votes)
        common_declaration = copy.deepcopy(
            representatives[first_site][PFDA_DECLARATION]
        )
        if len(votes) >= threshold:
            return PA_STATUS_ACCEPTED, common_declaration
        # Unique, conflict-free evidence short of the threshold keeps
        # the one common declaration but cannot be accepted yet.
        return PA_STATUS_INSUFFICIENT, common_declaration
    return PA_STATUS_INSUFFICIENT, None


def aggregate_prune_fork_decisions(
    items, prune_policy, site_policy, decision_site_policy,
    keyring, moment, issuer, version,
):
    """Aggregate multi-site prune aggregate fork decisions offline.

    ``items`` is a non-empty list; each item contains exactly a unique,
    non-empty str ``id`` and ``decision`` bytes produced by
    :func:`adjudicate_prune_aggregate_forks`; the whole batch structure
    is validated before any decision is parsed.  ``prune_policy`` is
    the shared invariant original ``{"batch", "sites", "threshold"}``
    pruning policy and ``site_policy`` the fork-proof site
    authorization policy the decisions were issued against;
    ``decision_site_policy`` carries exactly ``sites`` (a non-empty
    mapping of each site allowed to hand over decisions to its
    non-empty set of allowed positive key versions) and ``threshold``
    (a positive integer no greater than the site count).  ``keyring``
    follows the existing rules, ``moment`` is the current time and
    ``issuer``/``version`` name the aggregate signing credentials.  No
    file is read or written and no input is modified.

    Every decision is first re-verified on its own through the exact
    :func:`verify_prune_aggregate_fork_decision` rules -- canonical
    structure, both policy digest bindings and a full re-tally of the
    bound per-proof rows -- then authenticated against the current
    keyring by its exact payload issuer and key version, and finally
    authorized precisely against ``decision_site_policy`` with no
    fallback: a structurally illegal decision or one with a broken
    binding is recorded ``invalid`` with reason ``invalid`` (and
    carries no identity), unknown, revoked, not-yet-valid or expired
    credentials or a wrong signature ``unauthenticated``, and an
    authenticated but unauthorized site or key version
    ``unauthorized``, each rejecting only that item while the others
    continue.  A valid decision counts as the issuing site's complete
    declaration: the common fork edge set, the per-item conclusions
    (sorted by site then id, each entry carrying its conclusion, proof
    digest, authenticated fork edges or null, id, reason and site), the
    original-order proof digest vector and the overall status.  For one
    site, an exactly identical complete declaration counts once and
    repeats are ``duplicate``; any field-level difference is a
    ``contradiction``.  Distinct sites must agree on that same complete
    declaration -- any difference makes the aggregate ``conflicted``,
    the common declaration is bound null and no majority can outvote
    the disagreement.  One unique declaration backed by at least the
    threshold of distinct sites is ``accepted``; short of the threshold
    it stays ``insufficient`` but still carries that common
    declaration; with no valid vote the declaration is null.

    The result is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``.  The payload binds
    exactly ``inputs`` (each input decision's SHA-256 in the original
    input order, so a reordering is detectable), ``issuer``, ``items``
    (the per-decision rows sorted stably by site then id, each carrying
    ``conclusion``, the decision ``digest``, ``id``, ``issuer``,
    ``keyVersion``, ``reason`` and the authenticated ``declaration`` or
    null), ``keyVersion``, ``prunePolicyDigest``, ``sitePolicyDigest``,
    ``decisionSitePolicyDigest``, ``declaration`` (the one common
    complete declaration, or null), ``status`` and ``version`` (the
    integer 1).  The signature is the lowercase hex HMAC-SHA256 of the
    canonical compact payload bytes under the exact issuer/version key.
    A parameter, container or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty list, an empty or duplicate id or an illegal policy,
    threshold, moment, issuer or version raises :class:`ValueError`;
    unknown, revoked, not-yet-valid or expired aggregate credentials
    raise :class:`AuthenticationError`.
    """
    validated_items = _validated_pfda_decision_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_decision_site_policy = _validated_prune_batch_site_policy(
        decision_site_policy
    )
    validated_keyring = _validated_keyring(keyring)
    aggregate_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    site_policy_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    rows = [
        _aggregate_pfda_one(
            item,
            prune_policy_digest,
            site_policy_digest,
            validated_site_policy[ADJ_THRESHOLD],
            validated_decision_site_policy,
            validated_keyring,
            aggregate_moment,
        )
        for item in validated_items
    ]
    input_digests = [row[CP_DIGEST] for row in rows]
    status, common_declaration = _tally_pfda_rows(
        rows, validated_decision_site_policy[ADJ_THRESHOLD]
    )
    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, aggregate_moment
    )
    payload = {
        PFDA_INPUTS: input_digests,
        VD_ISSUER: issuer,
        ITEMS: rows,
        KEY_VERSION: version,
        PFDA_PRUNE_POLICY_DIGEST: prune_policy_digest,
        PFDA_SITE_POLICY_DIGEST: site_policy_digest,
        PFDA_DECISION_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_decision_site_policy)
        ).hexdigest(),
        PFDA_DECLARATION: common_declaration,
        STATUS: status,
        VERSION: PRUNE_FORK_DECISION_AGGREGATE_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _validated_pfda_declaration_entry(
    value: object, where: str, invalid=_pfda_invalid
) -> dict:
    """Validate one per-item conclusion entry inside a declaration."""
    if not isinstance(value, dict):
        raise TypeError(f"{where} entry must be an object")
    if set(value.keys()) != _PFDA_DECLARATION_ENTRY_KEYS:
        raise invalid(
            f"{where} entry must contain exactly the keys 'conclusion', "
            "'digest', 'edges', 'id', 'reason' and 'site'"
        )
    entry_id = value[ID]
    if not isinstance(entry_id, str):
        raise TypeError(f"{where} entry id must be a str")
    if entry_id == "":
        raise invalid(f"{where} entry id must be non-empty")
    digest = value[CP_DIGEST]
    if not isinstance(digest, str):
        raise TypeError(f"{where} entry digest must be a str")
    if not _prune_is_digest(digest):
        raise invalid(
            f"{where} entry digest must be 64 lowercase hex characters"
        )
    site = value[VD_ISSUER]
    if site is not None:
        if not isinstance(site, str):
            raise TypeError(f"{where} entry site must be a str or null")
        if site == "":
            raise invalid(f"{where} entry site must be non-empty")
    conclusion = value[ADJ_CONCLUSION]
    if not isinstance(conclusion, str):
        raise TypeError(f"{where} entry conclusion must be a str")
    if conclusion not in _PAFD_CONCLUSIONS:
        raise invalid(f"{where} entry conclusion is not known")
    reason = value[ADJ_REASON]
    if conclusion == _PAFD_CONCLUSION_VALID:
        if reason is not None:
            raise invalid(
                f"{where} entry reason must be null for a valid item"
            )
    else:
        if not isinstance(reason, str):
            raise TypeError(f"{where} entry reason must be a str")
        if reason not in _PAFD_REASONS:
            raise invalid(f"{where} entry reason is not known")
    if conclusion == _PAFD_CONCLUSION_INVALID:
        if reason not in _PAFD_INVALID_REASONS:
            raise invalid(
                f"{where} entry reason does not match an invalid item"
            )
    elif conclusion != _PAFD_CONCLUSION_VALID:
        if reason != conclusion:
            raise invalid(
                f"{where} entry reason must match its conclusion"
            )
    raw_edges = value[PAFD_EDGES]
    if raw_edges is not None:
        if not isinstance(raw_edges, list):
            raise TypeError(f"{where} entry edges must be a list or null")
        if not raw_edges:
            raise invalid(
                f"{where} entry edges must be non-empty for an "
                "authenticated proof"
            )
        edges = [
            _validated_pafd_edge(edge_value, where, invalid)
            for edge_value in raw_edges
        ]
        triples = _pac_fork_edge_triples(edges)
        if len(set(triples)) != len(triples):
            raise invalid(f"{where} entry edges must be unique")
        if list(triples) != sorted(triples):
            raise invalid(
                f"{where} entry edges must be sorted ascending"
            )
    else:
        edges = None
    identity_expected = reason != _PAFD_REASON_INVALID_PROOF
    if identity_expected:
        if site is None or edges is None:
            raise invalid(
                f"{where} an authenticated entry must carry its site and "
                "fork edges"
            )
    elif site is not None or edges is not None:
        raise invalid(
            f"{where} an invalid-proof entry must carry no site or fork "
            "edges"
        )
    return {
        ADJ_CONCLUSION: conclusion,
        CP_DIGEST: digest,
        PAFD_EDGES: edges,
        ID: entry_id,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _validated_pfda_declaration(
    value: object, where: str, invalid=_pfda_invalid,
    positional_proofs: bool = False,
) -> dict | None:
    """Structurally validate one complete declaration into a fresh dict.

    The declaration carries exactly ``common`` (the common fork edge
    set, or null), ``conclusions`` (the per-item conclusion entries,
    sorted by site then id), ``proofs`` (the proof digest vector) and
    ``status``; a conflicted status binds no common set and an accepted
    status must bind one.  With ``positional_proofs`` the proof vector
    must match the sorted per-entry digests term by term; otherwise only
    the two digest multisets must agree.
    """
    if value is None:
        return None
    if not isinstance(value, dict):
        raise TypeError(f"{where} must be an object or null")
    if set(value.keys()) != _PFDA_DECLARATION_KEYS:
        raise invalid(
            f"{where} must contain exactly the keys 'common', "
            "'conclusions', 'proofs' and 'status'"
        )
    status = value[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} status must be a str")
    if status not in _PAFD_STATUSES:
        raise invalid(f"{where} status is not a known status")

    common = value[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError(f"{where} common must be a list or null")
        if not common:
            raise invalid(
                f"{where} a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(edge_value, f"{where} common", invalid)
            for edge_value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise invalid(
                f"{where} common edges must be unique and sorted ascending"
            )
    else:
        common_edges = None
    if status == _PAFD_STATUS_CONFLICTED and common is not None:
        raise invalid(
            f"{where} a conflicted declaration must bind no common set"
        )
    if status == _PAFD_STATUS_ACCEPTED and common is None:
        raise invalid(
            f"{where} an accepted declaration must bind its common set"
        )

    raw_entries = value[PFDA_CONCLUSIONS]
    if not isinstance(raw_entries, list):
        raise TypeError(f"{where} conclusions must be a list")
    if not raw_entries:
        raise invalid(f"{where} conclusions must be non-empty")
    entries = [
        _validated_pfda_declaration_entry(entry_value, where, invalid)
        for entry_value in raw_entries
    ]
    entry_ids = [entry[ID] for entry in entries]
    if len(set(entry_ids)) != len(entry_ids):
        raise invalid(f"{where} conclusions must not repeat an id")
    expected_order = sorted(
        entries,
        key=lambda entry: (
            entry[VD_ISSUER] is not None,
            entry[VD_ISSUER] or "",
            entry[ID],
        ),
    )
    if [entry[ID] for entry in expected_order] != entry_ids:
        raise invalid(
            f"{where} conclusions must be sorted by site then id"
        )

    proofs = value[PFDA_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError(f"{where} proofs must be a list")
    if not proofs:
        raise invalid(f"{where} proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"{where} proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise invalid(
                f"{where} proof {position} digest must be 64 lowercase hex "
                "characters"
            )
    if len(proofs) != len(entries):
        raise invalid(
            f"{where} the conclusions must cover every proof and vice versa"
        )
    entry_digests = [entry[CP_DIGEST] for entry in entries]
    if positional_proofs:
        if proofs != entry_digests:
            raise invalid(
                f"{where} the bound proof digests must correspond term by "
                "term to the sorted conclusions"
            )
    elif sorted(proofs) != sorted(entry_digests):
        raise invalid(
            f"{where} the bound proof digests must equal the per-entry "
            "digests"
        )

    return {
        PAFD_COMMON: common_edges,
        PFDA_CONCLUSIONS: entries,
        PFDA_PROOFS: list(proofs),
        STATUS: status,
    }


def _parse_pfda(raw: object) -> tuple[dict, str]:
    """Validate aggregate bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a public field of the wrong JSON type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, ordering, row-shape or
    declaration-shape fault raises
    :class:`InvalidAggregateForkDecisionAggregateError`.  The policy
    digests, tally and credential bindings are checked by
    :func:`verify_prune_fork_decision_aggregate`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("aggregate packet must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pfda_invalid(
            "aggregate packet must end with the closing brace, no "
            "trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pfda_keys
        )
    except json.JSONDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("aggregate packet must be a JSON object")
    if set(data.keys()) != _PFDA_TOP_KEYS:
        raise _pfda_invalid(
            "aggregate packet must contain exactly the keys 'payload' and "
            "'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("aggregate packet signature must be a str")
    if not _prune_is_digest(signature):
        raise _pfda_invalid(
            "aggregate packet signature must be 64 lowercase hex characters"
        )

    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("aggregate packet payload must be an object")
    if set(payload.keys()) != _PFDA_PAYLOAD_KEYS:
        raise _pfda_invalid(
            "aggregate packet payload must contain exactly the keys "
            "'inputs', 'issuer', 'items', 'keyVersion', "
            "'prunePolicyDigest', 'sitePolicyDigest', "
            "'decisionSitePolicyDigest', 'declaration', 'status' and "
            "'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("aggregate payload issuer must be a str")
    if issuer == "":
        raise _pfda_invalid("aggregate payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("aggregate payload keyVersion must be an int")
    if key_version <= 0:

    if key_version <= 0:
        raise _pfda_invalid("aggregate payload keyVersion must be positive")
    for field in (
        PFDA_PRUNE_POLICY_DIGEST,
        PFDA_SITE_POLICY_DIGEST,
        PFDA_DECISION_SITE_POLICY_DIGEST,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"aggregate payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate payload {field} must be 64 lowercase hex "
                "characters"
            )
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("aggregate status must be a str")
    if status not in _PA_STATUSES:
        raise _pfda_invalid("aggregate status is not a known status")
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("aggregate payload version must be an int")
    if version != PRUNE_FORK_DECISION_AGGREGATE_VERSION:
        raise _pfda_invalid("aggregate payload version must be the integer 1")

    inputs = payload[PFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("aggregate inputs must be a list")
    if not inputs:
        raise _pfda_invalid("aggregate inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"aggregate input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate input {position} digest must be 64 lowercase "
                "hex characters"
            )

    rows = payload[ITEMS]
    if not isinstance(rows, list):
        raise TypeError("aggregate items must be a list")
    if not rows:
        raise _pfda_invalid("aggregate items must be a non-empty list")
    if len(rows) != len(inputs):
        raise _pfda_invalid(
            "the items must cover every input and vice versa"
        )
    seen_row_ids: set[str] = set()
    parsed_rows: list[dict] = []
    for position, row in enumerate(rows):
        where = f"aggregate item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _pfda_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _pfda_invalid(f"{where} id must be non-empty")
        if row_id in seen_row_ids:
            raise _pfda_invalid(f"{where} repeats an id")
        seen_row_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{where} issuer must be a str or null")
        if site == "":
            raise _pfda_invalid(f"{where} issuer must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _pfda_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _pfda_invalid(
                f"{where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _pfda_invalid(
                    f"{where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _pfda_invalid(
                    f"{where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _pfda_invalid(
                    f"{where} reason must match its conclusion"
                )
        else:
            raise _pfda_invalid(f"{where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _pfda_invalid(
                    f"{where} an authenticated or authorized row must carry "
                    "its issuer"
                )
        elif site is not None:
            raise _pfda_invalid(
                f"{where} an invalid row must carry no issuer"
            )
        raw_declaration = row[PFDA_DECLARATION]
        if conclusion == PA_CONCLUSION_INVALID:
            if raw_declaration is not None:
                raise _pfda_invalid(
                    f"{where} an invalid row must carry no declaration"
                )
            parsed_declaration = None
        else:
            parsed_declaration = _validated_pfda_declaration(
                raw_declaration, f"{where} declaration"
            )
            if parsed_declaration is None:
                raise _pfda_invalid(
                    f"{where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: row_key_version,
            ADJ_REASON: reason,
            PFDA_DECLARATION: parsed_declaration,
        })

    common_declaration = _validated_pfda_declaration(
        payload[PFDA_DECLARATION], "aggregate declaration"
    )

    normalized_payload = {
        PFDA_INPUTS: list(inputs),
        VD_ISSUER: issuer,
        ITEMS: parsed_rows,
        KEY_VERSION: key_version,
        PFDA_PRUNE_POLICY_DIGEST: payload[PFDA_PRUNE_POLICY_DIGEST],
        PFDA_SITE_POLICY_DIGEST: payload[PFDA_SITE_POLICY_DIGEST],
        PFDA_DECISION_SITE_POLICY_DIGEST: payload[
            PFDA_DECISION_SITE_POLICY_DIGEST
        ],
        PFDA_DECLARATION: common_declaration,
        STATUS: status,
        VERSION: PRUNE_FORK_DECISION_AGGREGATE_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _pfda_invalid(
            "aggregate packet encoding is not the canonical compact form"
        )
    return normalized_payload, signature


def _reconcile_pfda_declaration(
    declaration: dict, fork_threshold: int, where: str
) -> None:
    """Re-tally one bound declaration as the decision it claims to be.

    The declaration's per-item conclusion entries and original-order
    proof digest vector are re-tallied through the exact
    :func:`_reconcile_pafd` rules against the fork-proof site policy
    threshold, so a reordered entry, a wrong duplicate or contradiction
    marking, a tampered common set or a mis-stated status cannot hide
    inside a counted declaration.  Any mismatch raises
    :class:`InvalidAggregateForkDecisionAggregateError`.
    """
    synthetic_payload = {
        PAFD_COMMON: declaration[PAFD_COMMON],
        ITEMS: [
            {
                ADJ_CONCLUSION: entry[ADJ_CONCLUSION],
                PAFD_EDGES: entry[PAFD_EDGES],
                ID: entry[ID],
                KEY_VERSION: None,
                PAFD_FORK_PROOF_DIGEST: entry[CP_DIGEST],
                ADJ_REASON: entry[ADJ_REASON],
                VD_ISSUER: entry[VD_ISSUER],
            }
            for entry in declaration[PFDA_CONCLUSIONS]
        ],
        PAFD_PROOFS: declaration[PFDA_PROOFS],
        STATUS: declaration[STATUS],
    }
    try:
        _reconcile_pafd(synthetic_payload, fork_threshold)
    except InvalidAggregateForkDecisionError as exc:
        raise _pfda_invalid(f"{where}: {exc}") from exc


def _reconcile_pfda_aggregate(
    payload: dict, fork_threshold: int, decision_threshold: int
) -> None:
    """Re-derive every aggregate binding of a parsed aggregate payload.

    Re-tallies the per-decision rows the signature covers -- the
    original-order input digest bindings, row ordering, same-site
    duplicate and contradiction markings, cross-site complete
    declaration agreement, the threshold acceptance and the claimed
    common declaration and status -- and re-tallies every counted
    declaration against the fork-proof site policy threshold, without
    seeing any decision bytes.  Any mismatch raises
    :class:`InvalidAggregateForkDecisionAggregateError`.
    """
    rows = payload[ITEMS]
    inputs = payload[PFDA_INPUTS]

    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise _pfda_invalid("items must be sorted by issuer then id")
    if sorted(row[CP_DIGEST] for row in rows) != sorted(inputs):
        raise _pfda_invalid(
            "the bound input digests must equal the per-item digests"
        )

    # Deep-copy the parsed rows before the tally mutates their
    # conclusion/reason markings; the signed payload itself is compared
    # through freshly derived structures only.
    working_rows = copy.deepcopy(rows)
    derived_status, derived_declaration = _tally_pfda_rows(
        working_rows, decision_threshold
    )

    for expected_row, bound_row in zip(working_rows, rows):
        if expected_row[ADJ_CONCLUSION] != bound_row[ADJ_CONCLUSION]:
            raise _pfda_invalid(
                f"item {bound_row[ID]!r} has the wrong conclusion"
            )
        if expected_row[ADJ_REASON] != bound_row[ADJ_REASON]:
            raise _pfda_invalid(
                f"item {bound_row[ID]!r} has the wrong reason"
            )

    if payload[STATUS] != derived_status:
        raise _pfda_invalid(
            "the bound status does not match the tallied items"
        )
    bound_declaration = payload[PFDA_DECLARATION]
    if derived_declaration is None:
        if bound_declaration is not None:
            raise _pfda_invalid(
                "the common declaration must be null when no unique "
                "conflict-free declaration was tallied"
            )
    else:
        if bound_declaration is None:
            raise _pfda_invalid(
                "an aggregate over one unique conflict-free declaration "
                "must carry the common declaration"
            )
        if bound_declaration != derived_declaration:
            raise _pfda_invalid(
                "the bound common declaration does not match the tallied "
                "decisions"
            )

    # Every counted declaration must itself re-tally as the decision it
    # claims to be, purely from its bound conclusions and proof vector.
    for row in rows:
        declaration = row[PFDA_DECLARATION]
        if declaration is None:
            continue
        _reconcile_pfda_declaration(
            declaration, fork_threshold, f"aggregate item {row[ID]!r}"
        )
    if bound_declaration is not None:
        _reconcile_pfda_declaration(
            bound_declaration, fork_threshold, "aggregate declaration"
        )


def _verify_pfda_core(
    aggregate: bytes,
    validated_prune_policy: dict,
    validated_site_policy: dict,
    validated_decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork-decision aggregate from validated shared materials."""
    payload, signature = _parse_pfda(aggregate)
    expected_prune_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[PFDA_PRUNE_POLICY_DIGEST] != expected_prune_digest:
        raise _pfda_invalid(
            "prune policy digest does not match the prune policy"
        )
    expected_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_site_policy)
    ).hexdigest()
    if payload[PFDA_SITE_POLICY_DIGEST] != expected_site_digest:
        raise _pfda_invalid(
            "site policy digest does not match the site policy"
        )
    expected_decision_site_digest = hashlib.sha256(
        _prune_batch_site_policy_bytes(validated_decision_site_policy)
    ).hexdigest()
    if payload[PFDA_DECISION_SITE_POLICY_DIGEST] != (
        expected_decision_site_digest
    ):
        raise _pfda_invalid(
            "decision site policy digest does not match the decision "
            "site policy"
        )

    _reconcile_pfda_aggregate(
        payload,
        validated_site_policy[ADJ_THRESHOLD],
        validated_decision_site_policy[ADJ_THRESHOLD],
    )

    entry = _usable_checkpoint_key(
        validated_keyring,
        payload[VD_ISSUER],
        payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "prune fork decision aggregate signature does not match"
        )
    return payload


